effect.shader:
vec2 gmHash2v(vec2 p){
p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
return fract(sin(p) * 43758.5453123);
}
vec3 gmRgb2hsv(vec3 c){
vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
float d = q.x - min(q.w, q.y);
return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + 1e-10)), d / (q.x + 1e-10), q.x);
}
vec3 gmHsv2rgb(vec3 c){
vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
vec2 p = uv * vec2(cellSize, cellSize / aspect);
vec2 base = floor(p);
float f1 = 8.0; float f2 = 8.0; vec2 bestCell = base;
for (int j = -1; j <= 1; j++) {
for (int i = -1; i <= 1; i++) {
vec2 c = base + vec2(float(i), float(j));
vec2 pt = c + gmHash2v(c + seedShift);
float d = length(pt - p);
if (d < f1) { f2 = f1; f1 = d; bestCell = c; }
else if (d < f2) { f2 = d; }
}
}
vec4 srcCell = texture2DCv(inputImg.texture, clamp((bestCell + 0.5 + gmHash2v(bestCell + seedShift) - 0.5) / vec2(cellSize, cellSize / aspect), 0.0, 1.0));
vec3 pane = srcCell.rgb;
vec3 paneOrig = pane;
vec3 hsv = gmRgb2hsv(pane);
float rnd = gmHash2v(bestCell + seedShift * 1.7).x;
hsv.x = fract(hsv.x + (rnd - 0.5) * hueSpread);
hsv.y = clamp(hsv.y * (0.85 + 0.5 * rnd), 0.0, 1.0);
hsv.z = clamp(hsv.z * (0.9 + 0.3 * gmHash2v(bestCell + 5.5).x), 0.0, 1.0);
pane = mix(paneOrig, gmHsv2rgb(hsv), clamp(tintStrength, 0.0, 1.0));
float edge = (f2 - f1);
float leading = 1.0 - smoothstep(borderWidth * 0.08, borderWidth * 0.22, edge);
pane = mix(pane, vec3(0.045, 0.045, 0.055), leading);
float ga = radians(glossAngle);
float sheen = dot(normalize(vec2(cos(ga), sin(ga))), fract(p) - 0.5);
float gl = pow(max(1.0 - abs(sheen), 0.0), 3.0) * gloss * (1.0 - leading);
pane += gl * 0.5;
vec3 col = mix(pane, src.rgb, mixOriginal * 0.01);
gl_FragColor = vec4(col, src.a);
}
